download_artifact() {
	asset_base=$(printf '%s' "$ASSET_PATTERN" |
		sed -e "s/{name}/$NAME/g" -e "s/{version}/$TAG/g" -e "s/{os}/$OS/g" -e "s/{arch}/$ARCH/g")
	case "$OS" in
		darwin|windows) extensions='.zip .tar.gz .exe raw' ;;
		*) extensions='.tar.gz .zip .exe raw' ;;
	esac
