			executables=$(find "$extractdir" -type f -name "$executable_name" -print)
			[ "$(printf '%s\n' "$executables" | line_count)" -eq 1 ] ||
				fail "archive must contain exactly one executable named $executable_name"
			executable=$executables
		fi
		prepare_install "$executable" "$executable_name"
	done
}

commit_installs() {
	tab=$(printf '\t')
	while IFS="$tab" read -r install_tmp install_destination; do
		mv -f "$install_tmp" "$install_destination" ||
			fail "could not install ${install_destination##*/}"
		printf 'Installed %s to %s\n' "${install_destination##*/}" "$install_destination"
	done < "$install_manifest"
}

main() {
	parse_args "$@"
	for command in awk cat cut find mkdir mktemp rm sed tr wc; do
		need "$command"
	done

	TAG=$(github_release "$REPOSITORY" "$requested_tag") ||
		fail "could not determine release tag ${requested_tag:-latest}"
	OS=$(uname_os)
	ARCH=$(uname_arch)
	case "$OS/$ARCH" in
		linux/amd64|linux/arm64|darwin/amd64|darwin/arm64|windows/amd64|windows/arm64|freebsd/amd64|freebsd/arm64) ;;
		*) fail "unsupported platform: $OS/$ARCH" ;;
	esac
	GITHUB_DOWNLOAD="https://github.com/$REPOSITORY/releases/download"

	tmpdir=$(mktemp -d "${TMPDIR:-/tmp}/insmith.XXXXXX") ||
		fail "could not create temporary directory"
	install_manifest="$tmpdir/install-manifest"
	: > "$install_manifest"
	trap cleanup 0
	trap 'exit 1' HUP INT TERM

	log_info "found version: $TAG for $OS/$ARCH"
	download_artifact
	verify_artifact
	extract_artifact
	prepare_binaries
	commit_installs

	cleanup
	trap - 0 HUP INT TERM
}

main "$@"
